@startuml

enum SubscriptionType {
  Monthly
  Annual
}

enum ServiceType {
  WeightRoom
  SwimmingPool
  ClimbingWall
  Sauna
  TurkishBath
}

class Customer {
  + name : string
  + surname : string
  + age : int
  + address : string
  + profession : string
}

class Subscription {
  + type : SubscriptionType
}

class Service {
  + type : ServiceType
}

class WorkoutPlan {
  + frequency : int
}

class Exercise {
  + name : string
  + repetitions : int
}

class MedicalCheck {
  + date : date
  + weight : float
  + bodyFat : float
  + electrocardiogram : string
  + restingHeartbeat : int
  + stressHeartbeat : int
}

class MedicalStaff {
  + diet : string
  + fitnessLevel : string
}

class Gym {
  + computeMonthlyBalance()
  + computeYearlyBalance()
  + sendArrearsReminder()
  + sendMedicalCheckReminder()
}

Customer "1" -- "1" Subscription : has
Customer "1" -- "*" Service : requests
Customer "1" -- "0..1" WorkoutPlan : follows
Customer "1" -- "0..*" MedicalCheck : undergoes
Customer "0..1" -- "1" MedicalStaff : assistedBy
WorkoutPlan "1" *-- "*" Exercise : defines
Gym "1" -- "*" Customer : manages
Gym "1" -- "*" Subscription : offers
Gym "1" -- "*" Service : offers
Gym "1" -- "*" MedicalStaff : employs

@enduml

